-- generated by schema/bin/gen_ddl.py from contract EgD-CDK-FIELDS-v2 -- do not hand-edit, regenerate instead

CREATE TABLE IF NOT EXISTS cdk_employee_master (
    employee_key VARCHAR(24),
    service_advisor_number NUMBER(38,0),
    cashier_id VARCHAR(10),
    booker_number NUMBER(38,0),
    story_employee_number VARCHAR(10),
    technician_ids VARCHAR(40),
    comeback_service_advisor VARCHAR(10),
    comeback_technician VARCHAR(10),
    hours_technician_id NUMBER(38,0),
    parts_counter_employee_id NUMBER(38,0),
    outside_salesman_id NUMBER(38,0),
    punch_technician_id NUMBER(38,0),
    discount_user_id VARCHAR(20),
    discount_applied_by VARCHAR(20),
    manager_override_id VARCHAR(20),
    lookup_technician_id VARCHAR(10),
    lookup_service_advisor_id VARCHAR(10),
    employee_name VARCHAR(80),
    employee_department VARCHAR(10),
    employee_status VARCHAR(32),
    _rooftop_id VARCHAR(20),
    _extracted_at TIMESTAMP_NTZ,
    _source_route VARCHAR(16),
    _batch_id VARCHAR(64),
    PRIMARY KEY (employee_key)
);

